df = load_stock()
agora = datetime.now().strftime("%d/%m/%Y %H:%M")

st.markdown(f"""
<div class="topbar">
  <div class="brand">
    <img src="data:image/png;base64,{LOGO_B64}">
    <h1>CONSULTA DE ESTOQUE</h1>
    <p>Consulte pneus disponíveis, quantidade e valor unitário.</p>
  </div>
  <div class="status">● Atualizado em {agora}</div>
</div>
""", unsafe_allow_html=True)

total = int(df["quantidade"].sum()) if not df.empty else 0
nota = int(df.loc[df["origem"]=="PNEUS COM NOTA","quantidade"].sum()) if not df.empty else 0
diesel = int(df.loc[df["origem"]=="DIESEL PNEUS","quantidade"].sum()) if not df.empty else 0
modelos = len(df)

st.markdown(f"""
<div class="metric-grid">
  <div class="metric"><div class="label blue">TOTAL DE PNEUS</div><div class="value">{total:,}</div><div class="sub">unidades</div></div>
  <div class="metric"><div class="label green">PNEUS COM NOTA</div><div class="value">{nota:,}</div><div class="sub">unidades</div></div>
  <div class="metric"><div class="label orange">DIESEL PNEUS</div><div class="value">{diesel:,}</div><div class="sub">unidades</div></div>
  <div class="metric"><div class="label purple">MODELOS</div><div class="value">{modelos}</div><div class="sub">cadastrados</div></div>
</div>
""".replace(",", "."), unsafe_allow_html=True)

st.markdown('<div class="section"><div class="section-title">🔎 PESQUISAR ESTOQUE</div>', unsafe_allow_html=True)

busca = st.text_input("Buscar", placeholder="Ex.: 600/65R28, PIRELLI, TM95...", label_visibility="collapsed")

c1, c2, c3 = st.columns([1,1,1])
with c1:
    origem = st.selectbox("Origem", ["TODAS","PNEUS COM NOTA","DIESEL PNEUS"])

base = df if origem=="TODAS" else df[df["origem"]==origem]

with c2:
    marca = st.selectbox("Marca", ["TODAS"] + sorted(base["marca"].dropna().unique().tolist()))

with c3:
    mostrar_zero = st.toggle("Mostrar itens sem estoque", value=False)

st.markdown("</div>", unsafe_allow_html=True)

f = base.copy()
if marca != "TODAS":
    f = f[f["marca"]==marca]

if busca.strip():
    termo = busca.strip()
    f = f[
        f["descricao"].str.contains(termo, case=False, na=False) |
        f["marca"].str.contains(termo, case=False, na=False)
    ]

if not mostrar_zero:
    f = f[f["quantidade"] > 0]

f = f.sort_values(["marca","descricao"])

status_txt = "Somente itens disponíveis" if not mostrar_zero else "Incluindo itens sem estoque"
st.markdown(
    f'<div class="results-head"><div>🛞 <b>{len(f)}</b> modelos encontrados</div><div>{status_txt}</div></div>',
    unsafe_allow_html=True
)

cards = []
for row in f.itertuples():
    origem_txt = esc(row.origem)
    badge_class = "badge-diesel" if origem_txt == "DIESEL PNEUS" else "badge-nota"
    cards.append(f"""
    <div class="product-card">
      <div>
        <span class="badge {badge_class}">{origem_txt}</span>
        <div class="desc">{esc(row.descricao)}</div>
        <div class="meta"><b>Marca:</b> {esc(row.marca)}<br><b>Origem:</b> {origem_txt}</div>
      </div>
      <div class="stock-box">
        <div class="qty">✓ {int(row.quantidade)} unidades</div>
        <div class="price">{brl(row.preco_unitario)}</div>
        <div class="price-label">VALOR UNITÁRIO</div>
      </div>
    </div>
    """)

st.markdown('<div class="product-grid">' + "".join(cards) + '</div>', unsafe_allow_html=True)

st.markdown(
    f'<div class="footer-note">ⓘ Estoque atualizado automaticamente a cada 60 segundos. Última consulta: <b>{agora}</b>.</div>',
    unsafe_allow_html=True
)
